solution.rational_numbers.zig:
const std = @import("std");
pub const Rational = struct {
    numer: i64,
    denom: i64,
    pub fn init(n: i64, d: i64) Rational {
        std.debug.assert(d != 0);
        var x: u64 = @abs(n);
        var y: u64 = @abs(d);
        while (y != 0) {
            const z = x % y;
            x = y;
            y = z;
        }
        const g: @TypeOf(n) = @intCast(x);
        return .{ .numer = @divTrunc(n, g) * (if (d < 0) @as(i64, -1) else 1), .denom = @divTrunc(d, g) * (if (d < 0) @as(i64, -1) else 1) };
    }
    pub fn add(a: Rational, b: Rational) Rational {
        return init(a.numer * b.denom + b.numer * a.denom, a.denom * b.denom);
    }
    pub fn sub(a: Rational, b: Rational) Rational {
        return init(a.numer * b.denom - b.numer * a.denom, a.denom * b.denom);
    }
    pub fn mul(a: Rational, b: Rational) Rational {
        return init(a.numer * b.numer, a.denom * b.denom);
    }
    pub fn div(a: Rational, b: Rational) Rational {
        return init(a.numer * b.denom, a.denom * b.numer);
    }
    pub fn abs(a: Rational) Rational {
        return init(@intCast(@abs(a.numer)), a.denom);
    }
    pub fn pow(a: Rational, p: i32) Rational {
        var r = init(1, 1);
        const b = if (p < 0) init(a.denom, a.numer) else a;
        for (0..@abs(p)) |_| r = r.mul(b);
        return r;
    }
    pub fn realPow(a: Rational, base: f64) f64 {
        return std.math.pow(f64, base, @as(f64, @floatFromInt(a.numer)) / @as(f64, @floatFromInt(a.denom)));
    }
};

starter.rational_numbers.zig:
pub const Rational = struct {
    numer: i64,
    denom: i64,
    pub fn init(n: i64, d: i64) Rational {
        return .{ .numer = n, .denom = d };
    }
    pub fn add(a: Rational, b: Rational) Rational {
        _ = b;
        return a;
    }
    pub const sub = add;
    pub const mul = add;
    pub const div = add;
    pub fn abs(a: Rational) Rational {
        return a;
    }
    pub fn pow(a: Rational, p: i32) Rational {
        _ = p;
        return a;
    }
    pub fn realPow(a: Rational, b: f64) f64 {
        _ = a;
        return b;
    }
};

