// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("rational_numbers.zig");
test "normalized arithmetic and exponents" {
    const R = m.Rational;
    const a = R.init(1, 2);
    const b = R.init(2, 3);
    try t.expectEqualDeep(R.init(7, 6), a.add(b));
    try t.expectEqualDeep(R.init(-1, 6), a.sub(b));
    try t.expectEqualDeep(R.init(1, 3), a.mul(b));
    try t.expectEqualDeep(R.init(3, 4), a.div(b));
    try t.expectEqualDeep(R.init(1, 2), R.init(2, 4));
    try t.expectEqualDeep(R.init(-1, 2), R.init(1, -2));
    try t.expectEqualDeep(R.init(0, 1), R.init(0, -5));
    try t.expectEqualDeep(a, R.init(-1, 2).abs());
    try t.expectEqualDeep(R.init(8, 1), a.pow(-3));
    try t.expectEqualDeep(R.init(1, 8), a.pow(3));
    try t.expectEqualDeep(R.init(1, 1), a.pow(0));
    try t.expectApproxEqAbs(@as(f64, 3), R.init(1, 2).realPow(9), 0.000001);
}
